window.__sp = (function () {
// One entry per streaming service. To add a service, copy a block, change the
// addresses and words, and add its site to "host_permissions" in manifest.json.
//
// Words are matched against the visible text of buttons and links (lowercase).
// Netflix uses fixed "steps" (tested for real 2026-11-08). The others use a
// "walk": keep clicking the best match from "go" (earlier words win) until
// done words show up or nothing matches. Their addresses and words come from
// memory, not testing, so each needs a test-mode run before trusting it.

const LOGIN = '(/login|/signin|/sign-in|/sign_in|/ap/signin|/identity/|/welcome([/?#]|$)|accounts\\.google\\.com|idmsa\\.apple\\.com)';

// Words that only show up once a subscription is canceled.
const CANCELED_SIGNS = [
  'restart subscription', 'restart membership', 'resume subscription', 'resume membership',
  'reactivate', 'resubscribe', 'undo cancel', 'renew subscription', 'rejoin', 'subscribe again',
  'will be canceled on', 'will be cancelled on', 'subscription will end on', 'membership will end on'
];

const CANCEL_DONE = [
  'has been canceled', 'has been cancelled', 'cancellation is complete', 'cancellation complete',
  'cancellation confirmed', 'successfully canceled', 'successfully cancelled', "you've canceled",
  "you've cancelled", 'you have canceled', 'you have cancelled', 'subscription is canceled',
  'subscription is cancelled', 'subscription was canceled', 'subscription was cancelled',
  'membership was canceled', 'membership was cancelled', 'membership has ended'
];

// Final confirm words first, so they win over "go to the next page" words.
const CANCEL_GO = [
  'finish cancellation', 'complete cancellation', 'confirm cancellation', 'yes, cancel', 'yes cancel',
  'cancel anyway', 'i still want to cancel', 'still cancel', 'no thanks, cancel', 'end my benefits',
  'cancel my benefits', 'continue to cancel', 'continue cancellation', 'continue cancelling',
  'continue canceling', 'cancel subscription', 'cancel all subscriptions', 'cancel my subscription', 'cancel your subscription',
  'cancel membership', 'cancel plan', 'cancel trial', 'end membership', 'end my membership',
  'end subscription', 'no thanks', 'deactivate'
];

// Not "welcome back": Peacock shows that on the page BEFORE the final
// restart button (found 2026-11-08), so it doesn't prove anything.
const RESTART_DONE = [
  'we have restarted', 'we\'ve restarted', 'have restarted your', 'subscription has been restarted', 'subscription restarted', 'membership restarted',
  'has been reactivated', 'successfully resubscribed', 'has been renewed', 'subscription is active again'
];

const RESTART_GO = [
  'undo cancel request', 'undo cancellation', 'undo cancel', 'restart subscription', 'restart membership',
  'resume subscription', 'resume membership', 'reactivate subscription', 'reactivate', 'resubscribe',
  'renew subscription', 'rejoin', 'subscribe again', 'keep my subscription', 'keep subscription',
  'keep membership', 'keep my membership', 'continue membership', 'agree & subscribe',
  'agree and subscribe', 'start subscription', 'confirm'
];

const BILLED_ELSEWHERE = [
  { text: 'billed through', message: 'This is billed through another company (like Apple, Google Play, Roku or your phone or internet provider), so it has to be canceled there.' },
  { text: 'billed by', message: 'This is billed by another company (like Apple, Google Play, Roku or your phone or internet provider), so it has to be canceled there.' },
  { text: 'subscribed through', message: 'This was bought through another company (like Apple, Google Play or Roku), so it has to be canceled there.' }
];

// Builds a walk-style service. accountUrl is where the cancel button lives;
// cancelUrl is used instead if the service has a direct cancel page.
// ownBilling: how the page words it when the service bills you itself
// (e.g. HBO Max says "Billed Through WarnerMedia Direct"), so that doesn't
// count as "billed through another company".
function walker({ name, watchPattern, accountUrl, cancelUrl, extraCancel = [], extraRestart = [], note, tested = false, history, ownBilling = [], billingUrls }) {
  const blockers = BILLED_ELSEWHERE.map((b) => ({ ...b, unless: ownBilling }));
  return {
    name, note, tested, watchPattern, loginPattern: LOGIN, history,
    // Price and next billing date: pages checked in order until both are found.
    billing: { urls: billingUrls || [accountUrl] },
    cancel: {
      url: cancelUrl || accountUrl,
      checkUrl: accountUrl,
      // Extra words are "open the menu" buttons, so they go last: once the
      // menu is open, the real cancel button outranks them.
      go: [...CANCEL_GO, ...extraCancel],
      max: 7,
      blockers,
      doneWords: CANCEL_DONE,
      checkWords: [...CANCEL_DONE, ...CANCELED_SIGNS]
    },
    restart: {
      url: accountUrl,
      checkUrl: accountUrl,
      go: [...RESTART_GO, ...extraRestart],
      max: 5,
      blockers: [],
      doneWords: RESTART_DONE,
      checkWords: RESTART_DONE,
      goneWords: CANCELED_SIGNS
    }
  };
}

const SERVICES = {
  netflix: {
