    accountUrl: 'https://auth.hbomax.com/subscription',
    // No dated history found (2026-11-09). The home page's Continue Watching
    // row shows "N minutes remaining", which changes as soon as someone watches.
    history: { url: 'https://play.hbomax.com/', mode: 'snapshot', heading: 'continue watching' },
    ownBilling: ['billed through warnermedia', 'billed through warner bros', 'billed through hbo']
  }),

