  // then "Cancel Subscriptions"; restart = "Restart Subscriptions" twice
  // (the second page says "Welcome back!" and $0.00 today).
  peacock: walker({
    tested: true,
    name: 'Peacock',
    // No dated history (checked 2026-11-08; "My Stuff" is only a watchlist).
    // Reads the home page's "Continue Watching" row and counts a change as use.
    history: { url: 'https://www.peacocktv.com/watch/home', mode: 'snapshot', heading: 'continue watching' },
    // The plan page shows "Premium Monthly $12.99/month"; the account page has the date.
    billingUrls: ['https://www.peacocktv.com/account/plans/manage-plan?productId=D2C_SUBSCRIPTION_MONTH', 'https://www.peacocktv.com/account/plans'],
    watchPattern: /^https:\/\/www\.peacocktv\.com\/watch\/playback/,
    accountUrl: 'https://www.peacocktv.com/account/plans',
