      note: 'You finish this one: the app opens Paramount+ in Chrome and you press the last button.'
    }
  },

  prime: walker({
    name: 'Amazon Prime',
    watchPattern: /^https:\/\/www\.(amazon\.com\/gp\/video|primevideo\.com).*(autoplay=1|\/watch)/,
    accountUrl: 'https://www.amazon.com/mc',
    extraCancel: ['end membership', 'cancel my benefits', 'end my benefits'],
    extraRestart: ['keep my membership', 'continue membership', 'keep my benefits'],
    note: 'Canceling Prime also ends free shipping, not just Prime Video.'
  }),

  appletv: walker({
    name: 'Apple TV',
    watchPattern: /^https:\/\/tv\.apple\.com\/.+\/(episode|movie)\//,
    accountUrl: 'https://tv.apple.com/settings',
    extraCancel: ['manage subscription', 'manage subscriptions'],
    note: 'Most likely needs work: Apple handles subscriptions through your Apple account.'
  }),

  youtubepremium: walker({
    name: 'YouTube Premium',
    // Any YouTube video counts as using it, since Premium covers all of YouTube.
    watchPattern: /^https:\/\/www\.youtube\.com\/watch/,
    accountUrl: 'https://www.youtube.com/paid_memberships',
    extraCancel: ['manage membership'],
    extraRestart: ['manage membership']
  }),

  youtubetv: walker({
    name: 'YouTube TV',
    watchPattern: /^https:\/\/tv\.youtube\.com\/watch\//,
