// These functions run inside the streaming site's tab (injected by
// background.js), so each one must be fully self-contained.

// Finds a visible button whose text matches one of the phrases (earlier
// phrases win), then clicks it, or in test mode outlines it in red without
// clicking. Also stops early on a sign-in page, a blocker, or done words.
async function findAndClick(o) {
  const { phrases, testMode, loginPattern, blockers = [], timeoutMs = 12000, doneWords = [], exclude = [], stopAtCardForm = false,
          answerSurveys = false, extraExact = [] } = o;
  const CLICKABLE = 'button, a, [role="button"], input[type="submit"], summary, [aria-expanded]';
  const norm = (t) => (t || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const label = (e) => norm(e.innerText || e.value || e.getAttribute('aria-label'));
  const visible = (el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';

  if (new RegExp(loginPattern, 'i').test(location.href)) return { status: 'login' };

  for (let waited = 0; waited <= timeoutMs; waited += 500) {
    const pageText = norm(document.body && document.body.innerText);
    const done = doneWords.find((w) => pageText.includes(w));
    if (done) return { status: 'done', match: done };
    // Restarts never type card numbers. If the service asks for a card (the
    // one on file is gone or expired), stop and let the person finish here,
    // where their phone's own autofill can fill it in.
    if (stopAtCardForm) {
      const cardField = [...document.querySelectorAll('input')].some((i) => visible(i) &&
        (/^cc-(number|csc|exp)/.test(i.getAttribute('autocomplete') || '') ||
         /card ?number|cardnumber|cvv|cvc|security ?code/i.test((i.name || '') + ' ' + (i.id || '') + ' ' + (i.getAttribute('aria-label') || '') + ' ' + (i.placeholder || ''))));
      if (cardField) return { status: 'cardform' };
    }
    for (const b of blockers) {
      // "unless": wording that means it's billed by the service itself after all.
      if (pageText.includes(b.text) && !(b.unless || []).some((u) => pageText.includes(u))) {
        return { status: 'blocked', message: b.message };
      }
    }
    // Also look at elements tagged with data-uia (Netflix's fold-out boxes
    // aren't real buttons).
    const els = [...document.querySelectorAll(CLICKABLE + ', [data-uia]')].filter(visible);
    // Right after answering a survey: its "Continue" / "Next" / "Submit"
    // button, matched exactly (a loose "continue" would hit "Continue watching").
    for (const p of extraExact) {
      const el = els.filter((e) => label(e) === p && !exclude.includes(p)).at(-1);
      if (el) {
        if (testMode) { el.style.outline = '4px solid red'; el.style.outlineOffset = '3px'; return { status: 'found', text: p }; }
        el.click();
        return { status: 'clicked', text: p };
      }
    }
    for (const p of phrases) {
      const matches = els.filter((e) => {
        const t = label(e);
        return !exclude.includes(t) && (t === p || (t.startsWith(p) && t.length <= p.length + 15));
      });
      // Prefer real buttons; among those, the innermost one.
      const real = matches.filter((e) => e.matches(CLICKABLE));
      const el = (real.length ? real : matches).at(-1);
      if (el) {
        const text = label(el);
        el.scrollIntoView({ block: 'center' });
        if (testMode) {
          el.style.outline = '4px solid red';
          el.style.outlineOffset = '3px';
          return { status: 'found', text };
        }
        el.click();
        return { status: 'clicked', text };
      }
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  // A "Why are you leaving?" survey with no answer picked yet: choose the first
  // reason that isn't "Other" (those often want typing), then the caller looks
  // for its Continue / Next / Submit button.
  if (answerSurveys) {
    const radios = [...document.querySelectorAll('input[type="radio"], [role="radio"]')].filter(visible);
    const anyChecked = radios.some((r) => r.checked || r.getAttribute('aria-checked') === 'true');
    if (radios.length > 1 && !anyChecked) {
      const textOf = (r) => norm((r.labels && r.labels[0] && r.labels[0].innerText) || r.getAttribute('aria-label') ||
        (r.closest('label') && r.closest('label').innerText) || (r.parentElement && r.parentElement.innerText) || '');
      const pick = radios.find((r) => !/other|prefer not|something else/i.test(textOf(r))) || radios[0];
      const text = textOf(pick).slice(0, 60) || 'first option';
      if (testMode) { (pick.closest('label') || pick).style.outline = '4px solid red'; return { status: 'found', text: `survey answer "${text}"` }; }
      ((pick.labels && pick.labels[0]) || pick).click();
      return { status: 'answered', text };
    }
  }
  // List what buttons the page did have, so the right words can be added.
  const seen = [...new Set([...document.querySelectorAll(CLICKABLE)].filter(visible).map(label).filter(Boolean))].slice(0, 15);
  return { status: 'notfound', url: location.href, seen };
}

// Reads a watch history page (like Netflix's Viewing Activity) and returns the
// most recent date on it. Dates look like 11/7/26 (US format).
async function readHistory(o) {
  const { loginPattern, timeoutMs = 15000 } = o;
  if (new RegExp(loginPattern, 'i').test(location.href)) return { status: 'login' };
  const re = /\b(\d{1,2})\/(\d{1,2})\/(\d{4}|\d{2})\b/g;
  let text = '';
  for (let waited = 0; waited <= timeoutMs; waited += 500) {
    text = document.body ? document.body.innerText : '';
    const dates = [];
    for (const m of text.matchAll(re)) {
      let y = +m[3];
      if (y < 100) y += 2000;
      const d = new Date(y, +m[1] - 1, +m[2], 12);
      // Ignore impossible or future dates.
      if (d.getMonth() === +m[1] - 1 && d.getTime() <= Date.now() + 86400000) dates.push(d.getTime());
    }
    if (dates.length) {
      const pm = text.match(/activity for ([^\n]+)/i);
      return { status: 'ok', last: Math.max(...dates), count: dates.length, profile: pm ? pm[1].trim().slice(0, 40) : null };
    }
    if (waited >= 4000 && /no (viewing )?activity|haven.t watched anything/i.test(text)) return { status: 'empty' };
    await new Promise((r) => setTimeout(r, 500));
  }
  return { status: 'nodates', summary: text.replace(/\s+/g, ' ').trim().slice(0, 200) };
}

// For services with no dated history (like Peacock): reads the titles in a
// row such as "Continue Watching", so the caller can tell if it changed.
// If the site first asks "Who's watching?", picks the first adult profile and
// returns status "picked" (the caller then loads the page again).
async function readSnapshot(o) {
  const { loginPattern, heading, timeoutMs = 20000 } = o;
  // Also strips the invisible direction marks HBO Max puts around titles.
  const norm = (t) => (t || '').replace(/[⁦-⁩‎‏]/g, '').replace(/\s+/g, ' ').trim();
  const visible = (el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';
  if (new RegExp(loginPattern, 'i').test(location.href)) return { status: 'login' };

  if (/\/profiles?(\/|$|\?)/i.test(location.pathname + location.search) || /who.s watching/i.test(document.body ? document.body.innerText : '')) {
    const skip = /^(kids|kids profile|new profile|add profile|who.s watching\??|manage profiles|edit|edit profiles?|account|done|help)$/i;
    const els = [...document.querySelectorAll('button, a, [role="button"], li, div, span')].filter(visible);
    const el = els.find((e) => {
      const raw = (e.innerText || '').trim();
      return raw && !raw.includes('\n') && raw.length < 30 && !skip.test(raw) && /^[\p{L}0-9 .'_-]+$/u.test(raw);
    });
    if (el) {
      const name = norm(el.innerText);
      (el.closest('button, a, [role="button"], li') || el).click();
      return { status: 'picked', profile: name };
    }
  }

  const want = heading.toLowerCase();
  for (let waited = 0; waited <= timeoutMs; waited += 500) {
    // Find the row title by its text, whatever it's wrapped in (Peacock's
    // title sits next to an icon, so "an element with only this text" missed it).
    let h = null;
    const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let n = walk.nextNode(); n; n = walk.nextNode()) {
      if (norm(n.nodeValue).toLowerCase() === want && n.parentElement && visible(n.parentElement)) { h = n.parentElement; break; }
    }
    if (h) {
      // Climb to the row, but never past it: stop where the text no longer
      // starts with the row's title (that would be the next row up, 2026-11-09).
      let box = h;
      for (let i = 0; i < 8 && box.parentElement; i++) {
        if (box.querySelectorAll('a, [role="link"], li').length > 1) break;
        if (!norm(box.parentElement.innerText).toLowerCase().startsWith(want)) break;
        box = box.parentElement;
      }
      // Rows like HBO Max's only load their tiles once on screen.
      if (box.querySelectorAll('a, [role="link"], li').length === 0) {
        box.scrollIntoView({ block: 'center' });
        for (let w = 0; w < 8000 && box.querySelectorAll('a, [role="link"], li').length === 0; w += 500) {
          await new Promise((r) => setTimeout(r, 500));
        }
      }
      const items = [...new Set([...box.querySelectorAll('a, [role="link"], li')]
        .map((e) => norm(e.getAttribute('aria-label') || e.innerText))
        .filter((t) => t && t.toLowerCase() !== want && !t.toLowerCase().startsWith('menu for')))];
      return { status: 'ok', snapshot: items.slice(0, 20).join(' | '), count: items.length };
    }
    // The page may only draw rows as you scroll, so scroll down a bit each time.
    window.scrollBy(0, 1200);
    await new Promise((r) => setTimeout(r, 500));
  }
  // Couldn't find the row. Don't guess "empty": that would count as a change
  // and wrongly mark the service as watched (happened with Peacock 2026-11-09).
  return { status: 'nosection', message: `couldn't find the "${heading}" row on the page` };
}

// Reads a service's account page for its monthly price and next billing (or
// end) date, e.g. HBO Max "$18.49 per month … is due on Dec 2, 2026",
// Peacock "What you'll pay then: $12.99", Netflix "Ends November 16, 2026".
async function readBilling(o) {
  const { loginPattern, timeoutMs = 12000 } = o;
  if (new RegExp(loginPattern, 'i').test(location.href)) return { status: 'login' };
  const norm = (t) => (t || '').replace(/[⁦-⁩‎‏]/g, '').replace(/\s+/g, ' ').trim();
  const M = 'jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sept?(?:ember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?';
  const DATE = `((?:${M})\\.?\\s+\\d{1,2},?\\s+\\d{4}|\\d{1,2}\\/\\d{1,2}\\/\\d{4})`;
  const pricePatterns = [
    // Netflix plan page: "Current Plan … Monthly price $8.99 (pre-tax)"
    /monthly price[^$]{0,30}\$\s?(\d{1,3}\.\d{2})/i,
    /\$\s?(\d{1,3}\.\d{2})\s*(?:\/\s?mo(?:nth)?\b|per month|a month|monthly)/i,
    /(?:you'll pay(?: then)?|you will pay|next payment(?: of)?|amount due)[^$]{0,40}\$\s?(\d{1,3}\.\d{2})/i,
    /\$\s?(\d{1,3}\.\d{2})[^$]{0,60}?(?:is due|will be charged|renews)/i
  ];
  const dateRe = new RegExp(`(next payment(?: date)?|next billing(?: date)?|billing date|due on|is due on|renews?(?: on)?|will renew on|next charge|ends on|will be cancel+ed on|membership ends|ends)[^0-9a-z]{0,3}(?:[a-z ]{0,30}?)[: ]{0,3}${DATE}`, 'i');
  const parseDate = (s) => {
    const d = new Date(s.replace(/\bsept\b/i, 'Sep').replace(',', ''));
    return isNaN(d) ? null : d.getTime();
  };
  let text = '';
  for (let waited = 0; waited <= timeoutMs; waited += 500) {
    text = norm(document.body && document.body.innerText);
    let price = null;
    for (const re of pricePatterns) { const m = text.match(re); if (m) { price = parseFloat(m[1]); break; } }
    const dm = text.match(dateRe);
    const date = dm ? parseDate(dm[2]) : null;
    const kind = dm ? (/end|cancel/i.test(dm[1]) ? 'ends' : 'renews') : null;
    if (price !== null || date !== null) {
      return { status: 'ok', price, date, kind, dateText: dm ? dm[0].slice(0, 60) : null };
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  return { status: 'none', summary: text.slice(0, 200) };
}

// After the clicks, checks the page for signs the cancel or restart worked.
// doneWords: any one present means done. goneWords: if none of them are on a
// full page (and it isn't a sign-in page), that also means done.
function checkDone(doneWords, goneWords, loginPattern) {
  const text = (document.body && document.body.innerText || '').replace(/\s+/g, ' ').trim().toLowerCase();
  if (loginPattern && new RegExp(loginPattern, 'i').test(location.href)) return { done: false, match: null, summary: 'a sign-in page' };
  const match = doneWords.find((w) => text.includes(w));
  if (match) return { done: true, match, summary: text.slice(0, 300) };
  if (goneWords && goneWords.length && text.length > 200 && !goneWords.some((w) => text.includes(w))) {
    return { done: true, match: 'no cancel notice left on the account page', summary: text.slice(0, 300) };
  }
  return { done: false, match: null, summary: text.slice(0, 300) };
}

return { SERVICES, findAndClick, readHistory, readSnapshot, readBilling, checkDone };
})();
